const now = new Date();
const config = {
  workflowVersion: '2.0.0-phase1',
  timezone: 'Europe/Rome',
  seasonCode: '2026/27',
  sourceKey: 'lnd-veneto-cr',
  sourceName: 'Comitato Regionale Veneto - Comunicati Ufficiali',
  sourceUrl: 'https://www.figcvenetocalcio.it/archivio-comunicati',
  maxDocumentsPerRun: 3,
  telegramEnabled: false,
  telegramChatId: 'REPLACE_WITH_TELEGRAM_CHAT_ID'
};
if (config.telegramEnabled && config.telegramChatId.startsWith('REPLACE_')) {
  throw new Error('Configura telegramChatId prima di abilitare Telegram.');
}
return [{ json: {
  ...config,
  scheduledFor: now.toISOString(),
  runKey: 'lnd-watcher:' + now.toISOString().slice(0, 16)
}}];

const db = $input.first().json;
const config = $('Collector Config').first().json;
const run = $('Open Agent Run').first().json;
const source = $('Ensure Official Source').first().json;
const teams = Array.isArray(db.monitored_teams) ? db.monitored_teams : [];
if (!db.season_id || teams.length !== 4) {
  throw new Error('Contesto incompleto: attese Villanovese e tre avversarie.');
}
return [{ json: {
  ...config,
  runId: run.id,
  sourceId: source.id,
  seasonId: db.season_id,
  monitoredTeams: teams,
  competitions: Array.isArray(db.competitions) ? db.competitions : []
}}];

const html = String($json.html || '');
const ctx = $('Build Runtime Context').first().json;
const byFile = new Map();
const linkPattern = /href\s*=\s*["']([^"']*download\.ashx\?[^"']+)["']/gi;
let match;
while ((match = linkPattern.exec(html)) !== null) {
  const href = match[1].replace(/&amp;/gi, '&');
  let url;
  try { url = new URL(href, ctx.sourceUrl); } catch { continue; }
  const file = url.searchParams.get('file') || '';
  const decoded = decodeURIComponent(file);
  const name = decoded.split('/').pop() || '';
  const bulletin = name.match(/^Com_(\d+)\.pdf$/i);
  if (!bulletin) continue;
  url.searchParams.set('act', 'download');
  const number = Number(bulletin[1]);
  byFile.set(decoded.toLowerCase(), {
    bulletinNumber: String(number),
    canonicalUrl: url.toString(),
    sourceReference: decoded
  });
}
const candidates = [...byFile.values()]
  .sort((a, b) => Number(b.bulletinNumber) - Number(a.bulletinNumber))
  .slice(0, ctx.maxDocumentsPerRun);
if (!candidates.length) {
  return [{ json: { ...ctx, hasCandidate: false } }];
}
return candidates.map(candidate => ({
  json: {
    ...ctx,
    ...candidate,
    hasCandidate: true
  }
}));

const item = $input.first().json;
const text = String(item.text || '');
const dateMatch = text.slice(0, 12000).match(/\bDEL\s+(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})\b/i);
const publishedAt = dateMatch
  ? new Date(Date.UTC(Number(dateMatch[3]), Number(dateMatch[2]) - 1, Number(dateMatch[1]), 12)).toISOString()
  : '';
let sizeBytes = null;
try {
  const rawSize = $('Download PDF').item.binary?.data?.fileSize;
  if (typeof rawSize === 'number') sizeBytes = rawSize;
  else if (typeof rawSize === 'string' && /^\d+$/.test(rawSize)) sizeBytes = Number(rawSize);
} catch {}
return [{ json: {
  ...item,
  extractedText: text,
  publishedAt,
  sizeBytes
}}];

const document = $input.first().json;
const meta = $('Enrich PDF Metadata').item.json;
const ctx = $('Build Runtime Context').first().json;
const text = String(meta.extractedText || '');
const fold = value => String(value || '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toUpperCase();
const foldedText = fold(text);
const ranges = [];
for (const team of ctx.monitoredTeams) {
  const term = fold(team.official_name);
  let from = 0;
  while (term && (from = foldedText.indexOf(term, from)) !== -1) {
    ranges.push([Math.max(0, from - 2200), Math.min(text.length, from + term.length + 3200)]);
    from += term.length;
    if (ranges.length >= 20) break;
  }
}
ranges.sort((a, b) => a[0] - b[0]);
const merged = [];
for (const range of ranges) {
  const last = merged[merged.length - 1];
  if (last && range[0] <= last[1]) last[1] = Math.max(last[1], range[1]);
  else merged.push([...range]);
}
const excerpts = merged.map(([start, end]) => text.slice(start, end)).join('\n\n--- ESTRATTO ---\n\n').slice(0, 30000);
const teamList = ctx.monitoredTeams.map(t => ({
  id: t.team_id,
  name: t.official_name
}));
const competitionList = ctx.competitions.map(c => ({
  id: c.id,
  name: c.official_name,
  kind: c.kind,
  verification_status: c.verification_status
}));
const hasRelevantMentions = excerpts.trim().length > 0;
const aiPrompt = [
  'Analizza esclusivamente gli estratti del Comunicato Ufficiale LND Veneto forniti.',
  'Non usare conoscenza esterna e non inventare identità, competizioni, date o giornate.',
  'Cerca solo provvedimenti riferibili alle squadre monitorate.',
  'Non equiparare ammonizioni, diffide e giornate residue.',
  'Non classificare mai un dato come VERIFIED: usa PARSED, AMBIGUOUS o NON_VERIFICABILE.',
  'Se la competizione non è esplicita usa competition_kind NON_VERIFICABILE.',
  'Per page_number usa 0 quando la pagina non è ricavabile.',
  'Per campi sconosciuti usa stringa vuota o 0 come previsto dallo schema.',
  '',
  'SQUADRE MONITORATE:',
  JSON.stringify(teamList),
  '',
  'COMPETIZIONI DISPONIBILI NEL DATABASE:',
  JSON.stringify(competitionList),
  '',
  'COMUNICATO: ' + meta.canonicalUrl,
  'NUMERO: ' + meta.bulletinNumber,
  '',
  'ESTRATTI:',
  excerpts
].join('\n');
return [{ json: {
  documentId: document.id,
  canonicalUrl: document.canonical_url,
  bulletinNumber: document.bulletin_number,
  runId: ctx.runId,
  sourceId: ctx.sourceId,
  seasonId: ctx.seasonId,
  monitoredTeams: ctx.monitoredTeams,
  competitions: ctx.competitions,
  hasRelevantMentions,
  aiPrompt
}}];

const context = $('Build Relevant Excerpts').item.json;
let output = $json.output ?? $json;
if (typeof output === 'string') {
  try { output = JSON.parse(output); } catch { output = { measures: [], notes: ['JSON AI non valido'] }; }
}
const normalize = value => String(value || '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-zA-Z0-9]+/g, ' ').trim().toUpperCase();
const allowedTypes = new Set(['WARNING','DIFFIDA','SUSPENSION','EXPULSION','FINE','OTHER']);
const allowedStatuses = new Set(['PARSED','AMBIGUOUS','NON_VERIFICABILE']);
const rawMeasures = Array.isArray(output.measures) ? output.measures : [];
const accepted = [];
let unresolvedCompetition = false;
for (const measure of rawMeasures) {
  if (!allowedTypes.has(measure.measure_type)) continue;
  if (!String(measure.source_excerpt || '').trim()) continue;
  const team = context.monitoredTeams.find(t =>
    normalize(t.official_name) === normalize(measure.raw_team_name)
  );
  const matchingCompetitions = context.competitions.filter(c =>
    c.kind === measure.competition_kind
  );
  const competition = matchingCompetitions.length === 1 ? matchingCompetitions[0] : null;
  if (!competition) {
    unresolvedCompetition = true;
    continue;
  }
  let verificationStatus = allowedStatuses.has(measure.verification_status)
    ? measure.verification_status
    : 'NON_VERIFICABILE';
  if (!team && verificationStatus === 'PARSED') verificationStatus = 'AMBIGUOUS';
  const row = {
    hasMeasure: true,
    documentId: context.documentId,
    runId: context.runId,
    sourceId: context.sourceId,
    seasonId: context.seasonId,
    competitionId: competition.id,
    teamId: team?.team_id || null,
    personId: null,
    pageNumber: Number(measure.page_number) > 0 ? Number(measure.page_number) : null,
    sourceExcerpt: String(measure.source_excerpt).slice(0, 4000),
    rawTeamName: String(measure.raw_team_name || '').slice(0, 300) || null,
    rawPersonName: String(measure.raw_person_name || '').slice(0, 300) || null,
    measureType: measure.measure_type,
    quantity: Number(measure.quantity) > 0 ? Number(measure.quantity) : null,
    unit: String(measure.unit || '').slice(0, 80) || null,
    gamedays: Number(measure.gamedays) > 0 ? Number(measure.gamedays) : null,
    effectiveFrom: /^\d{4}-\d{2}-\d{2}$/.test(String(measure.effective_from || ''))
      ? measure.effective_from
      : null,
    verificationStatus,
    confidence: Math.max(0, Math.min(1, Number(measure.confidence) || 0)),
    canonicalUrl: context.canonicalUrl,
    bulletinNumber: context.bulletinNumber,
    telegramEnabled: $('Collector Config').first().json.telegramEnabled,
    telegramChatId: $('Collector Config').first().json.telegramChatId
  };
  row.measureFingerprintInput = JSON.stringify({
    documentId: row.documentId,
    pageNumber: row.pageNumber,
    team: normalize(row.rawTeamName),
    person: normalize(row.rawPersonName),
    type: row.measureType,
    gamedays: row.gamedays,
    excerpt: normalize(row.sourceExcerpt)
  });
  accepted.push({ json: row });
}
if (accepted.length) return accepted;
return [{ json: {
  hasMeasure: false,
  documentId: context.documentId,
  runId: context.runId,
  sourceId: context.sourceId,
  verificationResult: unresolvedCompetition ? 'AMBIGUOUS' : 'NOT_FOUND',
  evidence: {
    reason: unresolvedCompetition
      ? 'COMPETIZIONE_NON_MAPPATA_UNIVOCAMENTE'
      : 'NESSUN_PROVVEDIMENTO_RILEVANTE',
    ai_notes: Array.isArray(output.notes) ? output.notes : []
  }
}}];

const measure = $('Insert Measure Idempotently').item.json;
const cfg = $('Collector Config').first().json;
const team = measure.raw_team_name || 'Squadra non attribuita';
const person = measure.raw_person_name || 'Tesserato non attribuito';
const days = measure.gamedays ? '\nGiornate indicate: ' + measure.gamedays : '';
const message = [
  '⚽ LND-WATCHER 2.0 — nuovo elemento da verificare',
  '',
  'C.U. ' + ($('Build Relevant Excerpts').item.json.bulletinNumber || '?'),
  'Squadra: ' + team,
  'Tesserato: ' + person,
  'Tipo: ' + measure.measure_type + days,
  'Stato: ' + measure.verification_status,
  '',
  'Il dato non è ancora VERIFIED e non equivale automaticamente a giornate residue.',
  $('Build Relevant Excerpts').item.json.canonicalUrl
].join('\n').slice(0, 4000);
return [{ json: {
  runId: $('Build Runtime Context').first().json.runId,
  measureId: measure.id,
  telegramEnabled: cfg.telegramEnabled,
  telegramChatId: cfg.telegramChatId,
  telegramMessage: message
}}];
